<?php
 namespace Pterodactyl\Services\Dezerx\Catalogue; use Pterodactyl\Services\Dezerx\Text; use Pterodactyl\Services\Dezerx\Addons; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; use Illuminate\Http\Client\PendingRequest; class WorldCatalogue {  private const AGENT = 'KTS-Host/1.0 (world manager)'; private const BASE = 'https://api.curseforge.com'; private const GAME = 432; private const CLASS_WORLDS = 17; private const PER_PAGE = 24; private const SEARCH_TTL = 600; private const CATEGORY_TTL = 86400; private const FILES_TTL = 600; private const SORTS = [ 'popular' => 2, 'updated' => 3, 'downloads' => 6, 'name' => 4, ]; public function available(): bool { return $this->key() !== ''; } public function categories(): array { if (!$this->available()) { return []; } return Cache::remember('dezerx:worlds:categories', self::CATEGORY_TTL, function () { $response = $this->http()->get(self::BASE.'/v1/categories', [ 'gameId' => self::GAME, 'classId' => self::CLASS_WORLDS, ]); if ($response->failed()) { return []; } $categories = array_map(fn (array $row) => [ 'id' => (int) ($row['id'] ?? 0), 'name' => (string) ($row['name'] ?? ''), ], $response->json('data') ?? []); usort($categories, fn (array $a, array $b) => strcasecmp($a['name'], $b['name'])); return $categories; }); } public function search(string $query, int $page = 1, ?int $category = null, string $sort = 'popular'): array { if (!$this->available()) { return $this->empty($page, 'No CurseForge API key is configured, so there is no catalogue to browse. An administrator sets one on the World Manager addon.'); } $page = max(1, $page); $key = sprintf( 'dezerx:worlds:search:%s:%d:%s:%s', sha1(mb_strtolower($query)), $page, $category ?? 'all', $sort, ); return Cache::remember($key, self::SEARCH_TTL, function () use ($query, $page, $category, $sort) { $response = $this->http()->get(self::BASE.'/v1/mods/search', array_filter([ 'gameId' => self::GAME, 'classId' => self::CLASS_WORLDS, 'searchFilter' => $query, 'categoryId' => $category, 'sortField' => self::SORTS[$sort] ?? self::SORTS['popular'], 'sortOrder' => $sort === 'name' ? 'asc' : 'desc', 'pageSize' => self::PER_PAGE, 'index' => ($page - 1) * self::PER_PAGE, ], fn ($value) => $value !== null && $value !== '')); if ($response->failed()) { return $this->empty($page, $response->status() === 403 ? 'CurseForge refused this key for search. The key is valid, but /v1/mods/search has to be enabled on it by CurseForge.' : 'CurseForge could not be searched right now.'); } $total = min((int) ($response->json('pagination.totalCount') ?? 0), 10_000); return [ 'results' => array_map(fn (array $hit) => $this->world($hit), $response->json('data') ?? []), 'page' => $page, 'total' => $total, 'hasMore' => $page * self::PER_PAGE < $total, 'error' => null, ]; }); } public function files(string $id): array { if (!$this->available() || !ctype_digit($id)) { return []; } return Cache::remember("dezerx:worlds:files:{$id}", self::FILES_TTL, function () use ($id) { $response = $this->http()->get(self::BASE."/v1/mods/{$id}/files", ['pageSize' => 50]); if ($response->failed()) { return []; } $files = []; foreach ($response->json('data') ?? [] as $file) { $filename = (string) ($file['fileName'] ?? ''); if (!str_ends_with(mb_strtolower($filename), '.zip')) { continue; } $files[] = [ 'id' => (string) ($file['id'] ?? ''), 'name' => (string) ($file['displayName'] ?? $filename), 'filename' => $filename, 'gameVersions' => array_values(array_filter( (array) ($file['gameVersions'] ?? []), fn ($version) => (bool) preg_match('/^\d/', (string) $version), )), 'size' => (int) ($file['fileLength'] ?? 0), 'releasedAt' => $file['fileDate'] ?? null, 'releaseType' => (int) ($file['releaseType'] ?? 1), ]; } return $files; }); } public function download(string $id, string $fileId = ''): ?array { if (!$this->available() || !ctype_digit($id)) { return null; } $files = $this->files($id); if ($files === []) { return null; } $chosen = null; foreach ($files as $file) { if ($fileId === '' || $file['id'] === $fileId) { $chosen = $file; break; } } if ($chosen === null) { return null; } $response = $this->http()->get(self::BASE."/v1/mods/{$id}/files/{$chosen['id']}/download-url"); $url = $response->successful() ? (string) ($response->json('data') ?? '') : ''; if ($url === '') { return null; } return [ 'url' => $url, 'filename' => $chosen['filename'], 'size' => $chosen['size'], ]; } private function world(array $hit): array { $versions = []; foreach ((array) ($hit['latestFilesIndexes'] ?? []) as $index) { $version = (string) ($index['gameVersion'] ?? ''); if ($version !== '' && preg_match('/^\d/', $version) === 1) { $versions[$version] = true; } } $versions = array_keys($versions); usort($versions, fn (string $a, string $b) => version_compare($b, $a)); return [ 'id' => (string) ($hit['id'] ?? ''), 'name' => (string) ($hit['name'] ?? ''), 'summary' => Text::summary((string) ($hit['summary'] ?? ''), 180), 'author' => (string) ($hit['authors'][0]['name'] ?? ''), 'downloads' => (int) ($hit['downloadCount'] ?? 0), 'icon' => $hit['logo']['thumbnailUrl'] ?? null, 'screenshot' => $hit['screenshots'][0]['thumbnailUrl'] ?? null, 'url' => (string) ($hit['links']['websiteUrl'] ?? ''), 'categories' => array_values(array_filter(array_map( fn (array $category) => (string) ($category['name'] ?? ''), (array) ($hit['categories'] ?? []), ))), 'gameVersions' => array_slice($versions, 0, 3), 'updatedAt' => $hit['dateModified'] ?? null, ]; } private function empty(int $page, ?string $error = null): array { return ['results' => [], 'page' => $page, 'total' => 0, 'hasMore' => false, 'error' => $error]; } private function http(): PendingRequest { return Http::withHeaders([ 'x-api-key' => $this->key(), 'User-Agent' => self::AGENT, 'Accept' => 'application/json', ])->timeout(20); } private function key(): string { $addons = Addons::all(); $candidates = [ (string) ($addons[Addons::WORLD_MANAGER]['curseforge_key'] ?? ''), (string) (config('services.curseforge.key') ?? ''), (string) ($addons[Addons::MODPACK_MANAGER]['curseforge_key'] ?? ''), (string) ($addons[Addons::HYTALE_MOD_MANAGER]['curseforge_key'] ?? ''), ]; foreach ($candidates as $candidate) { if (trim($candidate) !== '') { return trim($candidate); } } return ''; } }